const text = $input.first().json.text || '';
const today = new Date();
today.setHours(0, 0, 0, 0);
const FLASH_DAYS = 7;
const todayStr = today.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Agent-only offers — excluded entirely
const AGENT_ONLY_OFFERS = [
  'Booked & Elevated',
  'Booked & Celebrated'
];

// Agent-only keywords — used to filter individual bullet segments
const AGENT_KEYWORDS = [
  'bonus commission',
  'travel agent',
  'travel advisor',
  'travel partner',
  'accredited',
  'arc,',
  'iatan',
  'clia',
  'commission'
];

const KNOWN_OFFERS = [
  'BOGO60',
  'Kids Sail Free',
  'Free 3rd & 4th Guests',
  'Summer Cyber Sale',
  'Summer Shorts Kicker',
  'Ovation of the Seas',
  'Up to $250 Off Flights',
  'Early Booking Bonus',
  'Last Minute Cruises'
];

const BW_LABEL = 'Booking Window:';
const allOffers = [];

for (let i = 0; i < KNOWN_OFFERS.length; i++) {
  const offerName = KNOWN_OFFERS[i];
  const nameIdx = text.indexOf(offerName);
  if (nameIdx === -1) continue;

  const bwIdx = text.indexOf(BW_LABEL, nameIdx);
  if (bwIdx === -1) continue;

  let valid = true;
  for (let j = 0; j < KNOWN_OFFERS.length; j++) {
    if (j === i) continue;
    const other = text.indexOf(KNOWN_OFFERS[j], nameIdx + offerName.length);
    if (other !== -1 && other < bwIdx) { valid = false; break; }
  }
  if (!valid) continue;

  const bwStart = bwIdx + BW_LABEL.length;
  const nextBullet = text.indexOf('•', bwStart);
  let bwText = nextBullet !== -1 ? text.substring(bwStart, nextBullet).trim() : text.substring(bwStart, bwStart + 150).trim();

  let endDateStr = bwText;
  const enDashIdx = bwText.indexOf('–');
  const emDashIdx = bwText.indexOf('—');
  const dashIdx = enDashIdx !== -1 ? enDashIdx : emDashIdx;
  if (dashIdx !== -1) endDateStr = bwText.substring(dashIdx + 1).trim();

  const endDate = new Date(endDateStr);
  const days = isNaN(endDate.getTime()) ? null : Math.ceil((endDate.getTime() - today.getTime()) / 86400000);

  allOffers.push({ name: offerName, bookingWindow: bwText, endDate: endDateStr, days: days });
}

const flashItems = allOffers.filter(function(o) { return o.days !== null && o.days >= 0 && o.days <= FLASH_DAYS; });

// Build display text — strip agent-only offers and agent-only bullet segments
function isAgentOnlySegment(seg) {
  const lower = seg.toLowerCase();
  for (let k = 0; k < AGENT_KEYWORDS.length; k++) {
    if (lower.indexOf(AGENT_KEYWORDS[k]) !== -1) return true;
  }
  return false;
}

function isAgentOnlyOfferBlock(seg) {
  const lower = seg.toLowerCase();
  for (let k = 0; k < AGENT_ONLY_OFFERS.length; k++) {
    if (lower.indexOf(AGENT_ONLY_OFFERS[k].toLowerCase()) !== -1) return true;
  }
  return false;
}

let displayText = text;
const termsIdx = displayText.indexOf('Terms & Conditions');
if (termsIdx !== -1) displayText = displayText.substring(0, termsIdx);

const rawParts = displayText.split('•');

// Filter out agent-only offer blocks and agent-only bullet segments
let inAgentBlock = false;
const filteredParts = [];
for (let i = 0; i < rawParts.length; i++) {
  const seg = rawParts[i];
  if (isAgentOnlyOfferBlock(seg)) {
    inAgentBlock = true;
    continue;
  }
  let startsConsumerOffer = false;
  for (let k = 0; k < KNOWN_OFFERS.length; k++) {
    if (seg.indexOf(KNOWN_OFFERS[k]) !== -1) { startsConsumerOffer = true; break; }
  }
  if (startsConsumerOffer) inAgentBlock = false;

  if (inAgentBlock) continue;
  if (isAgentOnlySegment(seg)) continue;

  filteredParts.push(seg);
}

let formattedHtml = filteredParts[0] || '';
for (let i = 1; i < filteredParts.length; i++) {
  formattedHtml += '<br><b style="color:#003087">&#9658;</b>&nbsp;' + filteredParts[i];
}

let emailHtml = '<html><body style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;color:#333;padding:0;">';
emailHtml += '<div style="background:#003087;padding:20px 24px;">';
emailHtml += '<h1 style="color:white;margin:0;font-size:22px;">Royal Caribbean — Daily Offers</h1>';
emailHtml += '<p style="color:#a0c0e8;margin:4px 0 0;font-size:14px;">' + todayStr + '</p>';
emailHtml += '</div><div style="padding:20px 24px;">';

if (flashItems.length > 0) {
  emailHtml += '<div style="background:#fff0f0;border:2px solid #c00;border-radius:6px;padding:16px;margin-bottom:20px;">';
  emailHtml += '<h2 style="color:#c00;margin:0 0 10px;font-size:16px;">&#9889; Flash Sale Alert — Book Fast!</h2>';
  for (let j = 0; j < flashItems.length; j++) {
    const item = flashItems[j];
    emailHtml += '<div style="padding:8px 0;border-bottom:1px solid #f8cccc;">';
    emailHtml += '<strong style="color:#c00;">' + item.name + '</strong><br>';
    emailHtml += '<span style="font-size:13px;">Closes: ' + item.endDate + ' — <b>' + item.days + ' day' + (item.days === 1 ? '' : 's') + ' left!</b></span>';
    emailHtml += '</div>';
  }
  emailHtml += '</div>';
}

emailHtml += '<h2 style="color:#003087;font-size:16px;border-bottom:2px solid #003087;padding-bottom:6px;">Current Offers</h2>';
for (let j = 0; j < allOffers.length; j++) {
  const offer = allOffers[j];
  const days = offer.days;
  let urgencyStyle = '';
  let urgencyText = '';
  if (days !== null && days >= 0) {
    if (days <= FLASH_DAYS) {
      urgencyStyle = 'color:#c00;font-weight:bold;';
      urgencyText = '&#9889; ' + days + ' day' + (days === 1 ? '' : 's') + ' left!';
    } else if (days <= 14) {
      urgencyStyle = 'color:#e67e00;';
      urgencyText = days + ' days left';
    } else {
      urgencyStyle = 'color:#2d6a2d;';
      urgencyText = days + ' days left';
    }
  }
  const isFlash = days !== null && days >= 0 && days <= FLASH_DAYS;
  const borderColor = isFlash ? '#c00' : '#003087';
  emailHtml += '<div style="border-left:4px solid ' + borderColor + ';padding:10px 14px;margin:8px 0;background:#f8faff;border-radius:3px;">';
  emailHtml += '<table width="100%" cellpadding="0" cellspacing="0"><tr>';
  emailHtml += '<td><strong style="color:#003087;">' + offer.name + '</strong></td>';
  if (urgencyText) emailHtml += '<td align="right" style="' + urgencyStyle + 'font-size:12px;white-space:nowrap;">' + urgencyText + '</td>';
  emailHtml += '</tr></table>';
  if (offer.bookingWindow) emailHtml += '<div style="font-size:12px;color:#666;margin-top:4px;">&#128197; ' + offer.bookingWindow + '</div>';
  emailHtml += '</div>';
}

emailHtml += '<details style="margin-top:16px;">';
emailHtml += '<summary style="cursor:pointer;color:#003087;font-weight:bold;padding:8px 0;">&#128196; View Full Offer Details</summary>';
emailHtml += '<div style="background:#f8faff;padding:14px;font-size:13px;line-height:2;border-radius:4px;margin-top:6px;">' + formattedHtml + '</div>';
emailHtml += '</details>';
emailHtml += '<p style="margin-top:20px;padding-top:12px;border-top:1px solid #eee;font-size:12px;color:#999;">';
emailHtml += 'Source: <a href="https://loyaltoyoualways.com/offers/" style="color:#003087;">Loyal To You Always</a>';
emailHtml += ' &nbsp;|&nbsp; <a href="https://creative.rccl.com/Sales/Royal/Promotions/Snapshot_of_Current_Offers.pdf" style="color:#003087;">View Full PDF</a>';
emailHtml += '</p></div></body></html>';

const subject = flashItems.length > 0
  ? '⚡ Flash Sale: ' + flashItems.map(function(f) { return f.name; }).join(' & ') + ' — ' + todayStr
  : 'Royal Caribbean Daily Digest — ' + todayStr;

return [{ json: { subject: subject, emailHtml: emailHtml } }];
